def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[background] * w for _ in range(h)]
    seen = [[False] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if seen[r][c]:
                continue
            seen[r][c] = True
            if color == background:
                continue

            q = deque([(r, c)])
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))

            if len(comp) >= 4:
                r0 = min(y for y, x in comp)
                r1 = max(y for y, x in comp)
                c0 = min(x for y, x in comp)
                c1 = max(x for y, x in comp)
                for y in range(r0, r1 + 1):
                    for x in range(c0, c1 + 1):
                        out[y][x] = color

    return out
